def objs(g,v):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==v and not seen[i][j]:
                st=[(i,j)]; cs={}; seen[i][j]=True
                while st:
                    a,b=st.pop(); cs[(a,b)]=v
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==v and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in cs]; cc=[p[1] for p in cs]
                out.append((min(rs),min(cc),max(rs),max(cc),len(cs)))
    return out
